{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to a user",
      "resource": "aws_iam_user_policy_attachment.privesc18-PassExistingRoleToNewGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The managed policy is attached directly to an IAM user, increasing the risk of access being retained or overlooked during permission reviews. Assigning the user to a group and attaching the policy to that group provides more manageable and auditable access control."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc18-PassExistingRoleToNewGlueDevEndpoint-group" {
  name = "privesc18-PassExistingRoleToNewGlueDevEndpoint-group"
}

resource "aws_iam_group_membership" "privesc18-PassExistingRoleToNewGlueDevEndpoint-membership" {
  name = "privesc18-PassExistingRoleToNewGlueDevEndpoint-membership"
  group = aws_iam_group.privesc18-PassExistingRoleToNewGlueDevEndpoint-group.name
  users = [aws_iam_user.privesc18-PassExistingRoleToNewGlueDevEndpoint-user.name]
}

resource "aws_iam_group_policy_attachment" "privesc18-PassExistingRoleToNewGlueDevEndpoint-user-attach-policy" {
  group      = aws_iam_group.privesc18-PassExistingRoleToNewGlueDevEndpoint-group.name
  policy_arn = aws_iam_policy.privesc18-PassExistingRoleToNewGlueDevEndpoint.arn
}
",
  "fix_summary": "Replaced the direct user policy attachment with a dedicated IAM group policy attachment and added the existing user to that group. The same managed policy remains assigned while access management is moved to the group level."
}
